    /**
     * Method to retrieve the Transaction via TransactionFetchOneSummary
     * @param 	summary TransactionFetchOneSummary 
     * @return 	TransactionFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Transaction getTransaction( TransactionFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "TransactionFetchOneSummary arg cannot be null" );
    	
    	Transaction entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Transaction
        	// --------------------------------------
        	CompletableFuture<Transaction> futureEntity = queryGateway.query(new FindTransactionQuery( new LoadTransactionFilter( summary.getTransactionId() ) ), ResponseTypes.instanceOf(Transaction.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Transaction with id " + summary.getTransactionId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Transactions
     *
     * @return 	List<Transaction> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Transaction> getAllTransaction() 
    throws ProcessingException {
        List<Transaction> list = null;

        try {
        	CompletableFuture<List<Transaction>> futureList = queryGateway.query(new FindAllTransactionQuery(), ResponseTypes.multipleInstancesOf(Transaction.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Transaction";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

